import { Button } from "@heroui/react"
import { PlusIcon } from '@radix-ui/react-icons'
import React, { useState } from 'react'
import { useStateContext } from '../../contexts/ContextProvider'
import PreparationsFormModal from './PreparationsFormModal'


function AddPreparation() {
    const [openEditModal, setopenEditModal] = useState(false)
    const [modalTitle, setmodalTitle] = useState("Add New Preparation")
    const {currentColor}=useStateContext()
    const [updated, setUpdated] = useState(false)
    const handleAddAction = () => {
       
        setopenEditModal(true)
        setmodalTitle("Add new preparation")
       
    }
  return (
    <div className='w-full h-screen flex items-center justify-center'><Button
    style={{ background: currentColor }}
    onClick={handleAddAction}
    className="bg-transparent rounded text-white"
    endContent={<PlusIcon />}
    size="lg"
>
   {modalTitle}
</Button>
{openEditModal && <PreparationsFormModal openEditModal={openEditModal} setopenEditModal={setopenEditModal} updated={updated} setUpdated={setUpdated}  modalTitle={modalTitle} />}
</div>
  )
}

export default AddPreparation