import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Modal, ModalContent, ModalHeader, ModalBody, ModalFooter, Button, useDisclosure, Checkbox, Input, Link, Textarea, Select, SelectItem } from "@heroui/react";
import { Loading } from '../../components';
import { useFormik } from "formik";
import useApi from "../../hooks/useApi";
import { ToastContainer, toast } from "react-toastify";
import AsyncSelect from "react-select/async";
import makeAnimated from "react-select/animated"
import CreateSelect from "react-select/creatable";
import genericsApi from "../../api/drugs/genericsApi";
import countriesApi from "../../api/countriesApi";
import entityTypes from "../../data/entityTypes";
import entityOwnerships from "../../data/entityOwnerships";
import categoriesApi from "../../api/categoriesApi";
import countiesApi from "../../api/countiesApi";
import entitiesApi from "../../api/entitiesApi";
import formulationsApi from "../../api/drugs/formulationsApi";
import preparationsApi from "../../api/drugs/preparationsApi";


export default function PreparationsFormModal({ openEditModal, setopenEditModal, item, updated, setUpdated, modalTitle }) {
    // const { isOpen, onOpen, onOpenChange } = useDisclosure();
    const animatedComponent = makeAnimated();
    const [preparation, setPreparation] = useState(item ? item : null)
    const [errors, setErrors] = useState();
    const [isKenyan, setisKenyan] = useState(false)



    //Retrieve formulations
    const [formulations, setFormulations] = useState([])
    const formulationsActionsApi = useApi(formulationsApi.formulationsAction

    )
    const getFormulations = async () => {
        await formulationsActionsApi.request({
            "action": "GetFormulations"

        })
    }

    useEffect(() => {
        getFormulations()
    }, [])

    useEffect(() => {

        if (formulationsActionsApi.data && formulationsActionsApi.data.length) {

            setFormulations(formulationsActionsApi.data.map((i) => ({ label: i.title, value: i.id })))
        }

        console.log
            ('countriesActionsApi.data', formulationsActionsApi.data)
    }, [formulationsActionsApi.data])


    //Retrieve generics
    const [generics, setGenerics] = useState([])
    const genericsActionsApi = useApi(genericsApi.genericsAction)
    const getGenerics = async () => {
        await genericsActionsApi.request({
            "action": "GetGenerics"

        })
    }

    useEffect(() => {
        getGenerics()
    }, [])

    useEffect(() => {

        if (genericsActionsApi.data && genericsActionsApi.data.length) {

            setGenerics(genericsActionsApi.data.map((i) => ({ label: i.title, value: i.id })))
        }
        console.log('generics', generics)
    }, [genericsActionsApi.data])


    //

    const preparationsActionsApi = useApi(preparationsApi.preparationsAction);

    const handlePreparationAction = async (data) => {
        const result = await preparationsActionsApi.request(data);

        if (result.ok) {
            setUpdated(true)
            setopenEditModal(false)
        } else {
            setErrors(result.data.errors)
        }

    }

    useEffect(() => { }, [preparation])

    useEffect(() => {

        if (preparationsActionsApi.data) {
            if (preparationsActionsApi.data.category) {
                setPreparation(preparationsActionsApi.data.category)
            }
        }
    }, [preparationsActionsApi.data])

    useEffect(() => {
        if (errors && errors.length) {
            errors.map((x) => {
                toast.error(x);
            });
        }
    }, [errors]);

    const formik = useFormik({
        initialValues: {
            title: preparation ? preparation.title : '',
            description: preparation ? preparation.description : '',
            formulation: preparation ? { 'label': preparation.formulation_title, 'value': preparation.formulation } : { 'label': "Select formulation", 'value': "" },
            generics: preparation ? preparation.gen_array.map((i) => ({ label: i.title, value: i.id })) : []
        },

        validationSchema: Yup.object({
            title: Yup.string()
                .min(3, "Must be 15 characters or more")
                .required("Title is required"),
        }),
        onSubmit: (values, { resetForm }) => {
            //Dispatch action

            console.log('VALZ', values)
            setErrors([])
            let arr = [];
            if (values.generics && values.generics.length) {
                values.generics.map((x) => {
                    arr.push(x.value);
                });
            }

            if (item) {

                handlePreparationAction({
                    "action": "UpdatePreparation",
                    "preparation_details": {
                        "id": preparation.id,
                        "title": values.title,
                        "formulation": values.formulation.value,
                        "generics": arr,
                        "description": values.description,
                    }
                })
            } else {
                handlePreparationAction({
                    "action": "CreatePreparation",
                    "preparation_details": {
                        "title": values.title,
                        "formulation_id": values.formulation.value,
                        "generics": arr,
                        "description": values.description,

                    }
                })
            }




            resetForm();
        },
    });



    const handleSelectCountry = (value) => {
        console.log('Local entity', value)
        formik.setFieldValue("country", value)

        if (value.label === "KENYA") {
            setisKenyan(true)
        }

    }


    return (
        <>
            <Modal
                isOpen={openEditModal}
                placement="center"
            >
                <ModalContent>


                    {(onClose) => (
                        <>
                            <ToastContainer position="bottom-center" theme="colored" />

                            {preparationsActionsApi.loading ? <Loading /> : <form className="items-center grid grid-cols-1"
                                onSubmit={formik.handleSubmit}
                            > <ModalHeader className="flex flex-col gap-1 content-center">{modalTitle}</ModalHeader>
                                <ModalBody>



                                    <Input
                                        id="title"
                                        name="title"
                                        autoFocus
                                        label="Title"
                                        placeholder="Enter title"
                                        variant="bordered"
                                        type="text"
                                        onChange={formik.handleChange}
                                        onBlur={formik.handleBlur}
                                        defaultValue={formik.values.title}
                                        value={formik.values.title}
                                    />
                                    <div>
                                        <CreateSelect
                                            styles={{
                                                control: (baseStyles, state) => ({
                                                    ...baseStyles,
                                                    borderColor: state.isFocused ? 'black' : 'grey',
                                                    height: '56px',
                                                    borderRadius: '20px',
                                                }),
                                            }}
                                            id="formulation"
                                            key="formulation"
                                            name="formulation"
                                            components={animatedComponent}
                                            placeholder="Select entity formulation"
                                            isClearable
                                            value={formik.values.formulation}
                                            onChange={(value) => formik.setFieldValue("formulation", value)}
                                            options={formulations}
                                        />
                                        {formik.touched.formulation && formik.errors.formulation ? (
                                            <p className="text-red-500 text-sm">{formik.errors.formulation}</p>
                                        ) : null}
                                    </div>


                                    <div>
                                        <CreateSelect
                                            styles={{
                                                control: (baseStyles, state) => ({
                                                    ...baseStyles,
                                                    borderColor: state.isFocused ? 'black' : 'grey',
                                                    height: '56px',
                                                    borderRadius: '20px',
                                                }),
                                            }}
                                            id="generics"
                                            key="generics"
                                            name="generics"
                                            components={animatedComponent}
                                            placeholder="Add comprising generics"
                                            isClearable
                                            isMulti
                                            value={formik.values.generics}
                                            onChange={(value) => formik.setFieldValue("generics", value)}
                                            options={generics}
                                        />
                                        {formik.touched.generics && formik.errors.generics ? (
                                            <p color="danger">{formik.errors.generics}</p>
                                        ) : null}
                                    </div>
                                    <Textarea
                                        id="description"
                                        key="description"
                                        name="description"
                                        label="Description"
                                        placeholder="Type description"
                                        variant="bordered"
                                        defaultValue={formik.values.description}
                                        value={formik.values.description}
                                        onBlur={formik.handleBlur}
                                        onChange={formik.handleChange}
                                    />

                                </ModalBody>
                                <ModalFooter>
                                    <Button color="danger" variant="flat" onPress={() => setopenEditModal(false)}>
                                        Cancel
                                    </Button>
                                    <Button color="primary" type="submit" onPress={onClose}>
                                        Save
                                    </Button>
                                </ModalFooter>

                            </form>}


                        </>
                    )}
                </ModalContent>
            </Modal>
        </>
    );
}
